package com.queuewise.queue.application;

/**
 * Carries HTTP context for a call-next command so the service layer can populate
 * the audit record without depending on the servlet API.
 *
 * @param correlationId X-Correlation-Id request header (generated by the controller if absent).
 * @param ipAddress     Remote address of the requesting client.
 */
public record CallNextRequest(String correlationId, String ipAddress) { }
